mapper.select:
SELECT s.*, ss.average_rating as averageRating, ss.total_reviews as reviewCount, (6371 * acos(cos(radians(#{lat})) * cos(radians(s.latitude)) * cos(radians(s.longitude) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(s.latitude)))) AS distance, CASE WHEN s.status = 'OPEN' THEN true ELSE false END as isOpen FROM tb_store s LEFT JOIN tb_store_stats ss ON s.id = ss.store_id
AND s.category = #{category}
AND (6371 * acos(cos(radians(#{lat})) * cos(radians(s.latitude)) * cos(radians(s.longitude) - radians(#{lng})) + sin(radians(#{lat})) * sin(radians(s.latitude)))) <= #{maxDistance}
ORDER BY distance ASC
ORDER BY ss.average_rating DESC, distance ASC
ORDER BY ss.total_orders DESC, ss.average_rating DESC
ORDER BY s.name ASC
ORDER BY distance ASC
LIMIT #{size} OFFSET #{page}

SELECT COUNT(*)
FROM tb_store s


        AND s.category = #{category}


        AND (6371 * acos(cos(radians(#{lat})) * cos(radians(s.latitude))
        * cos(radians(s.longitude) - radians(#{lng}))
        + sin(radians(#{lat})) * sin(radians(s.latitude)))) <= #{maxDistance}
